arguments.command:
python - <<'PY'
import pandas as pd
from pymatgen.core import Structure
p=pd.read_csv('nlo_pool.csv')
for _,r in p.iterrows():
 s=Structure.from_str(r.poscar,fmt='poscar')
 try: sym=s.get_space_group_info(symprec=0.08)
 except: sym=('?',0)
 print(r.candidate_id, f'{r.formula:23}',f'{s.composition.reduced_formula:16}',len(s), str(sym), 'abc='+str(tuple(round(x,2) for x in s.lattice.abc)), 'ang='+str(tuple(round(x,1) for x in s.lattice.angles)),'V/at='+str(round(s.volume/len(s),1)))
PY

